WITH unpacked AS (SELECT id, service, log_ts, payload_json, COALESCE(context['region'], 'unknown') AS region_or_default, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs WHERE service = 'search') SELECT *, FIRST_VALUE(user_tier, TRUE) OVER (ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_user_tier, FIRST_VALUE(region_or_default, TRUE) OVER (PARTITION BY service ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_region_or_default FROM unpacked;
